extends SceneTree

func _init() -> void:
	var field = load("res://instancing/instance_field.gd").new()
	field.build()
	ResourceSaver.save(field.multimesh, "res://build/field.res")

	var box_min = Vector3(-1.0, 0.0, -3.0)
	var box_max = Vector3(5.0, 1.5, 0.0)
	var res = field.cull(box_min, box_max)

	var report = {
		"instance_count": field.multimesh.instance_count,
		"transform_format": field.multimesh.transform_format,
		"use_colors": field.multimesh.use_colors,
		"use_custom_data": field.multimesh.use_custom_data,
		"query_min": [box_min.x, box_min.y, box_min.z],
		"query_max": [box_max.x, box_max.y, box_max.z],
		"visible_indices": res.indices,
		"visible_count": res.count,
		"weight_sum": res.weight_sum,
		"flagged_count": res.flagged_count
	}
	var file = FileAccess.open("res://build/report.json", FileAccess.WRITE)
	file.store_string(JSON.stringify(report, ""))
	file.close()
	print("DONE")
	quit()

